const wardrobeMaterials=new Map();for(const part of [staff,...armStaff])part.traverse(n=>{if(!n.isMesh)return;const original=n.material;if(!wardrobeMaterials.has(original)){const copy=original.clone();wardrobeMaterials.set(original,copy);M.add(copy);}n.material=wardrobeMaterials.get(original);});
